    mad.lo.u32 %row, %blk_y, 16, %tid_y;   // row = blockIdx.y * 16 + threadIdx.y
    mad.lo.u32 %col, %blk_x, 16, %tid_x;   // col = blockIdx.x * 16 + threadIdx.x

    // -------------------------------------------------
    // Bounds check
    // -------------------------------------------------
    setp.ge.u32 %p, %row, %N;
    @%p bra DONE;
    setp.ge.u32 %p, %col, %N;
    @%p bra DONE;

    // -------------------------------------------------
