    // offset = (row * N + col) * sizeof(half)
    mul.wide.u32 %offset, %row, %N;          // row * N
    cvt.u64.u32 %tmp_ptr, %col;              // col as 64‑bit
    add.u64 %offset, %offset, %tmp_ptr;      // row*N + col
    shl.b64 %offset, %offset, 1;             // *2 bytes per half
    add.u64 %addrC, %C_g, %offset;           // final address of C element

    // -------------------------------------------------
    // Initialize accumulator (fp32)
    // -------------------------------------------------
    mov.f32 %c_f, 0.0;

    // -------------------------------------------------
    // Main K‑loop
    // -------------------------------------------------
    mov.u32 %k, 0;

K_LOOP:
    setp.ge.u32 %p, %k, %N;
    @%p bra K_END;

    // ---- Load A[row, k] -------------------------------------------------
    mul.wide.u32 %offset, %row, %N;          // row * N
    cvt.u64.u32 %tmp_ptr, %k;                // k as 64‑bit
    add.u64 %offset, %offset, %tmp_ptr;      // row*N + k
    shl.b64 %offset, %offset, 1;             // *2 bytes
    add.u64 %addrA, %A_g, %offset;           // address of A element
    ld.global.f16 %a_h, [%addrA];           // load half

