    mul.wide.u32 %offset, %k, %N;           // k * N
    cvt.u64.u32 %tmp_ptr, %col;              // col as 64‑bit
    add.u64 %offset, %offset, %tmp_ptr;      // k*N + col
    shl.b64 %offset, %offset, 1;             // *2 bytes
    add.u64 %addrB, %B_g, %offset;           // address of B element
    ld.global.f16 %b_h, [%addrB];           // load half

    // ---- Convert to fp32 and accumulate ---------------------------------
    cvt.f32.f16 %a_f, %a_h;
    cvt.f32.f16 %b_f, %b_h;
    fma.rn.f32 %c_f, %a_f, %b_f, %c_f;

    // ---- Increment k ----------------------------------------------------
    add.u32 %k, %k, 1;
    bra.uni K_LOOP;

K_END:
    // -------------------------------------------------
    // Write result back (fp16)
    // -------------------------------------------------
    cvt.rn.f16.f32 %c_h, %c_f;
    st.global.f16 [%addrC], %c_h;

DONE:
    ret;
}
