PTX_SOURCE = r'''
.version 7.8
.target sm_120
.address_size 64

.visible .entry matmul_fp16 (
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    //--- registers ---------------------------------------------------------
    .reg .pred   %p;
    .reg .u32    %tx, %ty;
    .reg .u32    %bx, %by;
    .reg .u32    %row, %col, %k, %N;
    .reg .u64    %A, %B, %C;
    .reg .u64    %addr, %tmp64;
    .reg .f16    %a, %b, %c;
    .reg .f32    %af, %bf, %sum;

    //--- load kernel parameters --------------------------------------------
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %N, [N];

    //--- thread/block indices -----------------------------------------------
    mov.u32 %tx, %tid.x;
    mov.u32 %ty, %tid.y;
    mov.u32 %bx, %ctaid.x;
    mov.u32 %by, %ctaid.y;

    //--- compute global row / column (tile size 16x16) ----------------------
    mad.lo.u32 %row, %by, 16, %ty;   // row = by*16 + ty
    mad.lo.u32 %col, %bx, 16, %tx;   // col = bx*16 + tx

    //--- bounds check -------------------------------------------------------
    setp.ge.u32 %p, %row, %N;
    @%p bra DONE;
    setp.ge.u32 %p, %col, %N;
    @%p bra DONE;

    //--- accumulator (FP32) --------------------------------------------------
    mov.f32 %sum, 0f0;

    //--- main K loop --------------------------------------------------------
    mov.u32 %k, 0;
K_LOOP:
    setp.ge.u32 %p, %k, %N;
    @%p bra K_DONE;

    //--- load A[row, k] (row‑major) ----------------------------------------
    mul.wide.u32 %addr, %row, %N;          // row * N
    cvt.u64.u32 %tmp64, %k;                // k
    add.u64 %addr, %addr, %tmp64;          // row*N + k
    shl.b64 %addr, %addr, 1;               // *2 (fp16 size)
    add.u64 %addr, %A, %addr;              // global address
    ld.global.f16 %a, [%addr];

    //--- load B[k, col] (row‑major) ----------------------------------------
    mul.wide.u32 %addr, %k, %N;            // k * N
    cvt.u64.u32 %tmp64, %col;              // col
    add.u64 %addr, %addr, %tmp64;          // k*N + col
    shl.b64 %addr, %addr, 1;               // *2
    add.u64 %addr, %B, %addr;
    ld.global.f16 %b, [%addr];

    //--- convert to FP32 and accumulate ------------------------------------
    cvt.f32.f16 %af, %a;
    cvt.f32.f16 %bf, %b;
    fma.rn.f32 %sum, %af, %bf, %sum;

    //--- k++ ---------------------------------------------------------------
    add.u32 %k, %k, 1;
    bra.uni K_LOOP;
K_DONE:

    //--- store C[row, col] -------------------------------------------------
    mul.wide.u32 %addr, %row, %N;          // row * N
    cvt.u64.u32 %tmp64, %col;              // col
    add.u64 %addr, %addr, %tmp64;          // row*N + col
    shl.b64 %addr, %addr, 1;               // *2
    add.u64 %addr, %C, %addr;
    cvt.f16.f32 %c, %sum;
    st.global.f16 [%addr], %c;

DONE:
    ret;
}
